insert into public.projects (title,country,region,office,agency,sector,year,status,relationship,description,source_url,source_title,verification,budget_usd,beneficiaries,published) select 'Refugee food assistance in Rwamwanja / Kamwenge','Uganda','Africa','ADRA Uganda','WFP','Food Security',2018,'Historical','Implementation partnership','June 2018 cooperation with WFP and Uganda’s Office of the Prime Minister to provide food assistance to more than 85,000 refugees in Kamwenge district.','https://adra.org/adra-partners-with-world-food-program-to-help-feed-85000-refugees-in-uganda','ADRA International press release (19 June 2018)','Source-backed',NULL,85000,true where not exists (select 1 from public.projects where title='Refugee food assistance in Rwamwanja / Kamwenge' and country='Uganda' and year=2018);
insert into public.projects (title,country,region,office,agency,sector,year,status,relationship,description,source_url,source_title,verification,budget_usd,beneficiaries,published) select 'Emergency food distributions in Kherson','Ukraine','Europe','ADRA Ukraine','WFP','Emergency Response',2023,'Historical','Operational partnership','ADRA and WFP partnered in the delivery of emergency assistance to households in Kherson, reported November 2023.','https://adra.org/adra-distributes-emergency-aid-in-kherson','ADRA International news (1 November 2023)','Source-backed',NULL,NULL,true where not exists (select 1 from public.projects where title='Emergency food distributions in Kherson' and country='Ukraine' and year=2023);
insert into public.projects (title,country,region,office,agency,sector,year,status,relationship,description,source_url,source_title,verification,budget_usd,beneficiaries,published) select 'COVID-19 food voucher assistance','Ecuador','Latin America & Caribbean','ADRA Ecuador','WFP','Food Security',2021,'Historical','Partner support; multiple supporters','ADRA reported food assistance for 16,584 families, supported by WFP and USAID. Amount attributed specifically to WFP is not published in this source.','https://adra.org/news-release-adra-helps-feed-more-than-16000-families-impacted-by-the-covid-19-pandemic-in-ecuador','ADRA International news (12 February 2021)','Source-backed',NULL,NULL,true where not exists (select 1 from public.projects where title='COVID-19 food voucher assistance' and country='Ecuador' and year=2021);
insert into public.projects (title,country,region,office,agency,sector,year,status,relationship,description,source_url,source_title,verification,budget_usd,beneficiaries,published) select 'Drought food assistance in Phalombe and Mulanje','Malawi','Africa','ADRA Malawi','WFP','Food Security',2016,'Historical','Assistance with WFP','ADRA Malawi assisted households affected by drought in Phalombe and Mulanje with WFP support, including Food for Assets activities.','https://adra.org/adra-responding-to-el-nino-drought-emergency-in-africa','ADRA International drought response report','Source-backed',NULL,NULL,true where not exists (select 1 from public.projects where title='Drought food assistance in Phalombe and Mulanje' and country='Malawi' and year=2016);
insert into public.projects (title,country,region,office,agency,sector,year,status,relationship,description,source_url,source_title,verification,budget_usd,beneficiaries,published) select 'Livelihoods for refugees and asylum seekers','Tunisia','Middle East & North Africa','ADRA Tunisia','UNHCR','Livelihoods',2016,'Historical','UNHCR-funded','ADRA’s 2016 annual report describes a UNHCR-funded livelihoods initiative supporting refugees and asylum seekers in Tunisia.','https://adra.org/wp-content/uploads/2020/02/2016-ADRA-Annual-Report.pdf','ADRA 2016 Annual Report, pp. 22–23','Source-backed',NULL,112,true where not exists (select 1 from public.projects where title='Livelihoods for refugees and asylum seekers' and country='Tunisia' and year=2016);
insert into public.projects (title,country,region,office,agency,sector,year,status,relationship,description,source_url,source_title,verification,budget_usd,beneficiaries,published) select 'WASH rehabilitation and hygiene promotion in Yao district','Chad','Africa','ADRA Chad','UNICEF','WASH',2016,'Historical','Implementation partnership','ADRA’s 2016 annual report describes a UNICEF-partnered WASH initiative involving rehabilitation of water points and hygiene promotion in Yao district.','https://adra.org/wp-content/uploads/2020/02/2016-ADRA-Annual-Report.pdf','ADRA 2016 Annual Report, pp. 22–23','Source-backed',NULL,NULL,true where not exists (select 1 from public.projects where title='WASH rehabilitation and hygiene promotion in Yao district' and country='Chad' and year=2016);
insert into public.projects (title,country,region,office,agency,sector,year,status,relationship,description,source_url,source_title,verification,budget_usd,beneficiaries,published) select 'Food assistance to displaced households in Lebanon','Lebanon','Middle East & North Africa','ADRA Lebanon','WFP','Emergency Response',2024,'Historical','Operational collaboration','ADRA reported collaborating with WFP and other agencies to deliver food parcels and electronic vouchers to displaced persons during the Lebanon crisis.','https://adra.org/bringing-relief-and-hope-adras-emergency-response-efforts-in-2024','ADRA International 2024 emergency response overview','Source-backed',NULL,NULL,true where not exists (select 1 from public.projects where title='Food assistance to displaced households in Lebanon' and country='Lebanon' and year=2024);
